          commentary: '配点2点。空欄 エ は同じ文に2回出てきて、1回目はプロトコル名、2回目は「エ サーバ」という形で使われる。HTTP を入れれば HTTP サーバ、つまり Web サーバとして自然に読める。ここで DHCP や DNS を入れると「DNS サーバから PAC ファイルをダウンロード」となって意味が通らない。==空欄に入れた語を本文に戻して読み直す==と、取り違えに気づける。',
